package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"net/http"
	"strconv"
	"strings"
	"time"
)

const maxBodyBytes = 1 << 20

type Event struct {
	ID        string
	Type      string
	CreatedAt time.Time
	Payload   []byte
}

type EventStore interface {
	Store(context.Context, Event) error
}

type eventPayload struct {
	ID      string `json:"id"`
	Type    string `json:"type"`
	Created int64  `json:"created"`
}

func NewHandler(secret string, store EventStore) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
	})
	mux.HandleFunc("POST /webhooks", webhookHandler(secret, store))
	return mux
}

func webhookHandler(secret string, store EventStore) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
		if err != nil {
			http.Error(w, "request body too large", http.StatusRequestEntityTooLarge)
			return
		}
		timestamp, suppliedSignature, ok := parseSignature(r.Header.Get("Signature"))
		if !ok || !validSignature(secret, timestamp, body, suppliedSignature) {
			http.Error(w, "invalid signature", http.StatusUnauthorized)
			return
		}

		var payload eventPayload
		if err := json.Unmarshal(body, &payload); err != nil || payload.ID == "" || payload.Type == "" {
			http.Error(w, "invalid event payload", http.StatusBadRequest)
			return
		}
		event := Event{ID: payload.ID, Type: payload.Type, CreatedAt: time.Unix(payload.Created, 0).UTC(), Payload: body}
		if err := store.Store(r.Context(), event); err != nil {
			http.Error(w, "could not store event", http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusOK)
	}
}

func parseSignature(header string) (timestamp string, signature []byte, ok bool) {
	parts := strings.Split(header, ",")
	var value string
	for _, part := range parts {
		key, candidate, found := strings.Cut(strings.TrimSpace(part), "=")
		if !found {
			return "", nil, false
		}
		switch key {
		case "t":
			if timestamp != "" || candidate == "" {
				return "", nil, false
			}
			if _, err := strconv.ParseInt(candidate, 10, 64); err != nil {
				return "", nil, false
			}
			timestamp = candidate
		case "v1":
			if value != "" || candidate == "" {
				return "", nil, false
			}
			value = candidate
		}
	}
	if timestamp == "" || value == "" {
		return "", nil, false
	}
	signature, err := hex.DecodeString(value)
	if err != nil || len(signature) != sha256.Size {
		return "", nil, false
	}
	return timestamp, signature, true
}

func validSignature(secret, timestamp string, body, supplied []byte) bool {
	if secret == "" {
		return false
	}
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(timestamp))
	mac.Write([]byte("."))
	mac.Write(body)
	return hmac.Equal(mac.Sum(nil), supplied)
}
package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"log"
	"net/http"
	"os"
	"time"

	_ "github.com/jackc/pgx/v5/stdlib"
)

func main() {
	secret := os.Getenv("MIRROR_WEBHOOK_SECRET")
	if secret == "" {
		log.Fatal("MIRROR_WEBHOOK_SECRET must be set")
	}
	databaseURL := os.Getenv("MIRROR_DATABASE_URL")
	if databaseURL == "" {
		log.Fatal("MIRROR_DATABASE_URL must be set")
	}

	db, err := sql.Open("pgx", databaseURL)
	if err != nil {
		log.Fatalf("open database: %v", err)
	}
	defer db.Close()
	if err := db.PingContext(context.Background()); err != nil {
		log.Fatalf("connect database: %v", err)
	}
	store := SQLStore{db: db}
	if err := store.Migrate(context.Background()); err != nil {
		log.Fatalf("migrate database: %v", err)
	}

	server := &http.Server{
		Addr:              ":8080",
		Handler:           NewHandler(secret, store),
		ReadHeaderTimeout: 5 * time.Second,
	}
	log.Printf("listening on %s", server.Addr)
	if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatal(err)
	}
}

// SQLStore persists events to Postgres.
type SQLStore struct{ db *sql.DB }

func (s SQLStore) Migrate(ctx context.Context) error {
	_, err := s.db.ExecContext(ctx, `
		CREATE TABLE IF NOT EXISTS events (
			id TEXT PRIMARY KEY,
			type TEXT NOT NULL,
			created_at TIMESTAMPTZ NOT NULL,
			payload JSONB NOT NULL
		)`)
	return err
}

func (s SQLStore) Store(ctx context.Context, event Event) error {
	_, err := s.db.ExecContext(ctx, `
		INSERT INTO events (id, type, created_at, payload)
		VALUES ($1, $2, $3, $4::jsonb)
		ON CONFLICT (id) DO NOTHING`, event.ID, event.Type, event.CreatedAt, event.Payload)
	if err != nil {
		return fmt.Errorf("insert event: %w", err)
	}
	return nil
}
